window.HOEREN_TESTS[36] = {"id":"bewerbung-und-job-suchen","name":"Bewerbung und Job suchen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Herr Schmidt, hier ist das Personalbüro Schwarz. Ihre Bewerbung ist eingegangen, wir laden Sie zum Vorstellungsgespräch am Donnerstag um 14 Uhr ein. Bitte bringen Sie Original-Zeugnisse mit, nicht nur eine Kopie der Bewerbung. Ein Foto brauchen Sie nicht. Das Gespräch dauert etwa eine Stunde.","gender":"f","q":"Was muss Herr Schmidt mitbringen?","opts":["Original-Zeugnisse.","Nur eine Kopie der Bewerbung.","Ein Foto."],"correct":0},{"transcript":"Hi Anna, hier ist Tom. Ich habe heute den Job-Vertrag bekommen, endlich nach drei Monaten Bewerbungen. Es ist die Stelle bei der kleinen Firma, nicht bei der großen Firma, die wir besprochen hatten. Ich suche nicht mehr, das Gehalt ist gut und die Arbeitszeit auch. Ich freue mich riesig!","gender":"m","q":"Welche Stelle hat Tom bekommen?","opts":["Bei der großen Firma.","Bei der kleinen Firma.","Er sucht noch."],"correct":1},{"transcript":"Liebe Bewerber, eine wichtige Information: Bitte schickt eure Bewerbung nur per E-Mail als PDF, nicht per Post. Persönlich vorbeibringen geht dieses Jahr auch nicht, wir haben alles digital gemacht. Anhänge bitte als PDF, maximal 5 MB insgesamt. Bewerbungsschluss ist der 30. April. Wir freuen uns auf eure Unterlagen.","gender":"f","q":"Wie soll die Bewerbung kommen?","opts":["Per Post.","Per E-Mail als PDF.","Persönlich vorbeibringen."],"correct":1},{"transcript":"Achtung an alle Arbeitssuchenden: Das Arbeitsamt bietet ab nächster Woche neue Workshops an. Bewerbung schreiben am Montag, Vorstellungsgespräch üben am Mittwoch, Lebenslauf optimieren am Freitag. Anmeldung ist nötig, über die Webseite oder telefonisch. Alle Workshops sind kostenlos, bitte kommt pünktlich und bringt einen Stift mit.","gender":"m","q":"Wann ist der Workshop zum Lebenslauf?","opts":["Freitag.","Mittwoch.","Montag."],"correct":0},{"transcript":"Hallo Frau Becker, hier ist Personalleiterin Hofer von Firma TechFit. Wir haben Ihre Bewerbung erhalten. Leider passt Ihr Profil nicht zu der ursprünglich beworbenen Stelle, das ist keine Absage für unser Haus. Wir haben eine andere, passendere Stelle, gleiches Team, ähnliche Aufgaben. Sind Sie interessiert? Bitte rufen Sie zurück.","gender":"f","q":"Was bietet die Personalleiterin an?","opts":["Die ursprünglich beworbene Stelle.","Eine Absage.","Eine andere passendere Stelle."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer sucht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Bewerbungsfrist endet schon an diesem Freitag."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Die Anzeigen liegen auf dem Tisch. Jeder sucht etwas anderes."},{"speaker":"Lukas","gender":"m","text":"Ich bewerbe mich als Programmierer. Die Firma braucht jemanden für das Handy."},{"speaker":"Lisa","gender":"f","text":"Du schreibst seit Jahren solche Sachen. Das passt genau."},{"speaker":"Lukas","gender":"m","text":"Bewirbt sich jemand von euch als Ingenieur?"},{"speaker":"Lisa","gender":"f","text":"Nein. Als Ingenieur bewirbt sich keiner."},{"speaker":"Lukas","gender":"m","text":"Du stehst gern vor einer Klasse voller Kinder."},{"speaker":"Lisa","gender":"f","text":"Ich suche eine Stelle als Lehrerin. Die Grundschule gefällt mir am besten."},{"speaker":"Lukas","gender":"m","text":"Tom rechnet fehlerlos und bleibt dabei ganz ruhig."},{"speaker":"Lisa","gender":"f","text":"Tom will Buchhalter werden. Ein Büro in der Stadt sucht genau das."},{"speaker":"Lukas","gender":"m","text":"Sara hilft am Wochenende schon auf der Station."},{"speaker":"Lisa","gender":"f","text":"Sara bewirbt sich als Krankenschwester. Die Klinik hat drei offene Stellen."},{"speaker":"Lukas","gender":"m","text":"Bewirbt sich noch jemand als Architekt?"},{"speaker":"Lisa","gender":"f","text":"Nein. Architekt ist es auch nicht."},{"speaker":"Lukas","gender":"m","text":"Tim redet leicht mit Kunden an der Kasse."},{"speaker":"Lisa","gender":"f","text":"Tim sucht eine Stelle als Verkäufer im Einzelhandel. Der Laden um die Ecke braucht noch Leute."},{"speaker":"Lukas","gender":"m","text":"Dann schicken wir die Mappen heute Abend noch raus."},{"speaker":"Lisa","gender":"f","text":"Ich lese meine Unterlagen vorher noch einmal durch."}],"options":[{"letter":"a","text":"Lehrerin"},{"letter":"b","text":"Ingenieur"},{"letter":"c","text":"Programmierer"},{"letter":"d","text":"Verkäufer im Einzelhandel"},{"letter":"e","text":"Architekt"},{"letter":"f","text":"Buchhalter"},{"letter":"g","text":"Krankenschwester"},{"letter":"h","text":"Polizist"},{"letter":"i","text":"Arzt"}],"items":[{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"a"},{"person":"Tom","correct":"f"},{"person":"Sara","correct":"g"},{"person":"Tim","correct":"d"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Bewerber","gender":"m","text":"Wie viele Tage Urlaub hat man bei Ihnen am Anfang? 25, 27 oder schon 30 Tage?"},{"speaker":"Chefin","gender":"f","text":"Standard 25 Tage, nach 5 Jahren 27, nach 10 Jahren 30. Am Anfang also 25."},{"speaker":"Bewerber","gender":"m","text":"Verstehe, am Anfang 25 Tage, nicht 27 und nicht 30. Und Krankheitstage extra?"},{"speaker":"Chefin","gender":"f","text":"Bei Krankheit zahlen wir bis 6 Wochen volles Gehalt. Der Urlaub bleibt extra."},{"speaker":"Bewerber","gender":"m","text":"Das klingt fair, danke für die klare Information."}],"q":"Wie viele Urlaubstage am Anfang?","opts":["30 Tage.","27 Tage.","25 Tage."],"correct":2},{"lines":[{"speaker":"Personalerin","gender":"f","text":"Wir laden Sie zum zweiten Vorstellungsgespräch ein. Diese Woche, nicht erst nächste Woche."},{"speaker":"Bewerber","gender":"m","text":"Wunderbar, wann denn? Mittwoch oder Freitag? Nächste Woche wäre spät."},{"speaker":"Personalerin","gender":"f","text":"Diese Woche Mittwoch oder Freitag, je nachdem, was Ihnen passt. Erst nächste Woche geht nicht, der Chef ist dann weg."},{"speaker":"Bewerber","gender":"m","text":"Mittwoch, Freitag habe ich einen anderen Termin."},{"speaker":"Personalerin","gender":"f","text":"Mittwoch um 11 Uhr dann, bitte bringen Sie Ihre Zeugnisse mit."}],"q":"Wann ist das Gespräch?","opts":["Mittwoch.","Freitag.","Erst nächste Woche."],"correct":0},{"lines":[{"speaker":"Bewerberin","gender":"f","text":"Mein Lebenslauf ist nicht gut. Können Sie helfen? Workshop, Einzel-Beratung oder nur Online-Hilfe?"},{"speaker":"Berater","gender":"m","text":"Klar, wir haben Workshops, oder Einzel-Beratung. Online-Hilfe gibt es auch, aber die ist kürzer."},{"speaker":"Bewerberin","gender":"f","text":"Einzel ist mir lieber, mehr persönlich. Workshop und Online-Hilfe möchte ich nicht."},{"speaker":"Berater","gender":"m","text":"Termin Donnerstag um 10 Uhr für die Einzel-Beratung?"},{"speaker":"Bewerberin","gender":"f","text":"Perfekt, Donnerstag um 10, danke, das hilft mir wirklich."}],"q":"Was wählt die Bewerberin?","opts":["Einen Workshop.","Einzel-Beratung.","Online-Hilfe."],"correct":1},{"lines":[{"speaker":"Mutter","gender":"f","text":"Wie lief das Gespräch? Nimmst du die Stelle, suchst du weiter, oder gehst du ins Ausland?"},{"speaker":"Sohn","gender":"m","text":"Okay, die Chefin war nett, aber das Gehalt ist niedriger als erwartet."},{"speaker":"Mutter","gender":"f","text":"Nimmst du die Stelle trotzdem? Ins Ausland musst du ja nicht."},{"speaker":"Sohn","gender":"m","text":"Eigentlich nicht, ich suche weiter. Die Stelle nehme ich nicht, und ins Ausland gehe ich auch nicht."},{"speaker":"Mutter","gender":"f","text":"Gut, dann helfen wir dir nächste Woche mit neuen Bewerbungen."}],"q":"Was macht der Sohn?","opts":["Nimmt die Stelle.","Sucht weiter.","Geht ins Ausland."],"correct":1},{"lines":[{"speaker":"Chef","gender":"m","text":"Wir möchten Sie als neue Mitarbeiterin einstellen. Start 1. Juni, 15. Juni oder 1. Juli?"},{"speaker":"Bewerberin","gender":"f","text":"Wirklich? Wann fange ich an? 1. Juli wäre spät, 1. Juni bin ich noch in Urlaub."},{"speaker":"Chef","gender":"m","text":"1. Juni wäre uns recht. 1. Juli ist zu spät für das Team."},{"speaker":"Bewerberin","gender":"f","text":"Da bin ich noch in Urlaub. Ab 15. Juni, geht das?"},{"speaker":"Chef","gender":"m","text":"15. Juni passt auch, dann nicht 1. Juni und nicht 1. Juli."}],"q":"Wann fängt sie an?","opts":["1. Juni.","1. Juli.","15. Juni."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Klein, einer Personalleiterin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Klein, Sie arbeiten seit 15 Jahren als Personalleiterin. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Klein","gender":"f","text":"Ich habe BWL studiert und in einer Firma als normale Mitarbeiterin angefangen. Dann hat mich die Chefin gefragt, ob ich in die Personalabteilung wechseln möchte. Erst war ich skeptisch — Geld zählen lag mir mehr. Aber jetzt liebe ich Menschen-Arbeit mehr."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie genau?"},{"speaker":"Klein","gender":"f","text":"Bewerbungen sortieren, Vorstellungsgespräche führen, neue Mitarbeiter einarbeiten. Auch Probleme zwischen Kollegen lösen, manchmal auch Mitarbeiter entlassen — das ist immer schwer."},{"speaker":"Reporter","gender":"m","text":"Worauf achten Sie bei Bewerbungen?"},{"speaker":"Klein","gender":"f","text":"Sehr wichtig: ein klarer Lebenslauf ohne Lücken. Auch ein persönliches Anschreiben, kein Standard-Text. Notendurchschnitt ist weniger wichtig, als viele denken — Erfahrung und Persönlichkeit zählen mehr."},{"speaker":"Reporter","gender":"m","text":"Was sind häufige Fehler?"},{"speaker":"Klein","gender":"f","text":"Rechtschreibfehler im Lebenslauf — sehr schlimm! Auch zu lange Anschreiben. Und beim Vorstellungsgespräch sich nicht über die Firma informieren — das merken wir sofort."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie jungen Menschen?"},{"speaker":"Klein","gender":"f","text":"Sich nicht verstecken. Ehrlich sein über Schwächen. Praktika machen, früh anfangen. Und sich nicht aus dem Konzept bringen lassen, wenn etwas mal schief läuft."}],"items":[{"q":"Mitarbeiter entlassen ist für sie leicht.","correct":"nein"},{"q":"Frau Klein war zuerst Buchhalterin, nicht Personalleiterin.","correct":"nein"},{"q":"Notendurchschnitt ist das Wichtigste bei Bewerbungen.","correct":"nein"},{"q":"Rechtschreibfehler im Lebenslauf sind ein großes Problem.","correct":"ja"},{"q":"Sie rät jungen Menschen, viele Praktika zu machen.","correct":"ja"}]}]};
